assert_eq!(23_i16.next_multiple_of(8), 24);
assert_eq!(16_i16.next_multiple_of(-8), 16);
assert_eq!(23_i16.next_multiple_of(-8), 16);
assert_eq!((-16_i16).next_multiple_of(8), -16);
assert_eq!((-23_i16).next_multiple_of(8), -16);
assert_eq!((-16_i16).next_multiple_of(-8), -16);
assert_eq!((-23_i16).next_multiple_of(-8), -24);
```

